import type { PhysicalReading } from './perturbationEvidence';
import { EVIDENCE_TABS } from './evidenceTabs';
import { ALPHAGENOME_SOURCES } from './alphagenomeEvidence';
import { BURIAL_RSA_BANDS, PACKING_NEIGHBOUR_BANDS } from './burialEvidence';

/**
 * Research guides explain meaning; they never classify a variant or duplicate cut-points.
 * See doc/TRANSLATIONAL_PHILOSOPHY.md. Each entry must answer an unfamiliar researcher's
 * question, explain the reading, state its limit, and offer a next step with provenance.
 * The source-record inspector remains the authority for this run's values and served model.
 */
export interface ResearchGuide {
  title: string;
  group: string;
  question: string;
  answer: string;
  reading: string;
  limit: string;
  next: string;
  related: string[];
  source?: { label: string; url: string };
}

const source = (label: string, url: string) => ({ label, url });
const calibration = source('ClinGen computational evidence calibration', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9748256/');
const af = source('AlphaFold DB: confidence and limitations', 'https://alphafold.ebi.ac.uk/faq');
const esm = source('ESM models and variant scoring', 'https://github.com/facebookresearch/esm');
const gnomad = source('gnomAD help', 'https://gnomad.broadinstitute.org/help');
const interpro = source('InterPro: interpreting annotations', 'https://www.ebi.ac.uk/training/online/courses/interpro-quick-tour/');
const guide = (title: string, group: string, question: string, answer: string, reading: string, limit: string, next: string, related: string[], reference?: ResearchGuide['source']): ResearchGuide =>
  ({ title, group, question, answer, reading, limit, next, related, source: reference });

export const RESEARCH_GUIDES: Record<string, ResearchGuide> = {
  variant_identity: guide('Variant identity & numbering', 'Foundations', 'Are all these results about the same change?',
    'A residue number only identifies a position within a particular protein sequence. Transcripts, isoforms and genome assemblies can give different coordinates for the same biological change.',
    'Read the accession, transcript, assembly and reported versus modelled notation. A mapped position must refer to the sequence used by the structure or predictor.',
    'Matching gene names or residue numbers alone does not establish that two records describe the same allele. An unverified mapping limits interpretation.',
    'Check the identity and mapping information before comparing results or exporting them.', ['structure_guide', 'population', 'missing_data'], source('HGVS sequence variant nomenclature', 'https://hgvs-nomenclature.org/stable/')),
  missing_data: guide('Missing, zero & unavailable', 'Foundations', 'Does an empty result mean that nothing changed?',
    'No. Zero is a returned value; missing means the method did not supply a usable result. A failed request also differs from a source that was searched successfully and returned no record.',
    'Read the state and reason beside the source: running, no result, unsupported input or provider error. Coverage tells you how much was actually assessed.',
    'Missing scores must not become zero, benign, normal, or a negative finding. A fixed-backbone method cannot measure a backbone response to mutation.',
    'Inspect the availability reason. Retry a failed request when offered, or use evidence from a method that covers the input.', ['model_provenance', 'coverage', 'foldx']),
  coverage: guide('Evidence coverage', 'Foundations', 'How much of the question was assessed?',
    'Coverage describes the sources, positions, tissues or records for which usable evidence is available.',
    'Read the denominator: three available models out of six requested is different from three out of three. A partial attribution vector or sequence window describes only its reported subset.',
    'Completeness is not correctness, and a high count does not guarantee independent evidence. Unassessed regions remain unknown.',
    'Inspect missing sources and the analysis window before summarising a result.', ['missing_data', 'model_disagreement', 'shap']),
  model_provenance: guide('Model identity & fallbacks', 'Foundations', 'Which model actually produced this result?',
    'The returned result may come from a different model or execution tier than the one requested. Provenance records what served the value.',
    'Read the served model, source release, input structure and fallback reason in the source record. This guide describes methods generally; it does not establish which one ran for your variant.',
    'A preferred model name in settings is not proof of execution. Scores from different model families or versions may have different meanings and scales.',
    'Use the run-specific provenance when citing, comparing or reproducing a reading.', ['llr', 'uncertainty', 'variant_identity']),
  uncertainty: guide('Uncertainty & confidence', 'Foundations', 'What does a confidence value or error bar actually tell me?',
    'Different methods quantify different uncertainties: variability between repeated runs, expected prediction error, or confidence in a coordinate model.',
    'Read what the interval measures, its units and how it was obtained. A spread across engines is disagreement; repeated-run standard deviation describes repeatability.',
    'Identical runs do not prove accuracy. A structure confidence score is not confidence in a clinical conclusion, and a benchmark error is not an individual variant’s error bar.',
    'Check the method and input limitations alongside any interval. If uncertainty was not estimated, treat it as unknown.', ['plddt', 'model_disagreement', 'ddg']),
  evidence_strength: guide('Evidence strength & classification', 'Foundations', 'How does a score contribute to a clinical interpretation?',
    'ACMG/AMP criteria organise evidence about disease causation. Some computational scores have published calibrations that map score ranges to evidence strengths.',
    'Distinguish a published calibrated band, an author’s operating point and an app-defined display mark. The inspector shows the criterion actually recorded by this run’s rule engine.',
    'A coloured band or an author’s “pathogenic” prediction is not a final clinical classification. Several correlated predictions are not automatically several independent lines of evidence.',
    'Read the rule trace, the applicable gene/disease context and any withheld or unconfirmed criteria.', ['predictors', 'model_disagreement', 'clinical_assertions'], calibration),
  model_disagreement: guide('Agreement & disagreement', 'Foundations', 'What should I do when the models disagree?',
    'Models use different inputs and answer different questions. A stability prediction can differ from a sequence constraint score without either being a direct contradiction.',
    'Compare like quantities first, using the displayed sign convention. Inspect each contributor and the number of usable results. Agreement counts describe the returned set.',
    'A majority is not a calibrated probability. Shared training data, features or component models can make apparently separate votes dependent.',
    'Check model identity, structure quality and coverage, then look for independent experimental or curated evidence.', ['ddg', 'predictors', 'uncertainty'], calibration),
  population: guide('Population data', 'Workspaces', 'How often has this allele been observed?',
    'Population records describe observations in sampled cohorts. Frequency places the variant in population context and helps assess whether it fits a proposed disease model.',
    'Read allele count (AC), the number of assessed alleles (AN), frequency (AF), ancestry group and source filters together. The engine input row is a derived input, not another cohort.',
    'Rarity alone does not establish pathogenicity. No returned record does not guarantee that a well-covered site was observed to have zero alternate alleles.',
    'Inspect counts and coverage in the source records and then the recorded frequency-rule trace.', ['allele_frequency', 'constraint', 'missing_data'], gnomad),
  allele_frequency: guide('Allele frequency · AC / AN / AF', 'Metrics', 'What does a very small frequency mean?',
    'Allele frequency (AF) is the fraction of assessed chromosome copies carrying the allele. AC counts alternate copies; AN counts the copies assessed.',
    'Compare the frequency with its denominator and population. Percentage and fraction are different displays of the same quantity: 0.01 as a fraction is 1%.',
    'Small denominators make rare observations uncertain. Cohorts can overlap and their counts must not be added without accounting for that overlap.',
    'Check the exact counts, ancestry and filtering before interpreting absence or rarity.', ['population', 'coverage'], gnomad),
  constraint: guide('Gene constraint · LOEUF, pLI & missense Z', 'Metrics', 'Does this gene tolerate variation in the population?',
    'Constraint compares observed variation with an expectation. It describes depletion of a class of variants across a gene, rather than the effect of your particular substitution.',
    'Lower LOEUF indicates stronger depletion of predicted loss-of-function variants. Higher missense Z indicates stronger missense depletion. pLI and LOEUF are different summaries and should retain their own labels.',
    'A constrained gene can contain benign variants. Gene-level loss-of-function constraint does not demonstrate the mechanism of a particular missense variant.',
    'Read the constraint release and gene–disease mechanism alongside variant-level evidence.', ['gene_disease', 'population'], gnomad),
  clinical_assertions: guide('ClinVar assertions', 'Sources', 'What have clinical submitters concluded?',
    'ClinVar collects submitted interpretations of variants in relation to conditions, with review status and supporting information.',
    'Read the condition, submitter, evaluation date, review status and whether submissions conflict. Keep source assertions distinct from the app’s recorded assessment.',
    'An assertion is not a new experiment. Conflicting or older submissions require examination, and training a predictor on ClinVar can create overlap with this evidence.',
    'Open the source record and examine the relevant submissions and their supporting evidence.', ['evidence_strength', 'variant_identity'], source('ClinVar review status', 'https://www.ncbi.nlm.nih.gov/clinvar/docs/review_status/')),
  gene_disease: guide('Gene–disease relationships', 'Workspaces', 'Is this gene established to cause the disease being considered?',
    'Gene–disease evidence evaluates a relationship between a gene, a condition and an inheritance model. It supplies the context in which a variant can be interpreted.',
    'Compare validity assertions with the same disease and inheritance mode. Mechanism labels such as loss of function describe the proposed disease mechanism.',
    'A strong gene–disease relationship does not classify every variant in that gene. Different diseases associated with one gene can have different mechanisms.',
    'Choose the relevant disease frame and inspect its source assertions before connecting molecular findings to disease.', ['clinical_assertions', 'expression', 'species'], source('ClinGen gene–disease validity', 'https://clinicalgenome.org/curation-activities/gene-disease-validity/')),
  expression: guide('Expression & tissue context', 'Workspaces', 'Where is this gene expressed, and does that help interpret the finding?',
    'Expression datasets describe RNA abundance in sampled tissues or cell types. They help identify biological contexts worth investigating.',
    'Read the measurement type, tissue, units, aggregation and source cohort. Compare values within a compatible dataset and scale.',
    'RNA abundance is not protein activity. Low or missing expression in an adult bulk tissue does not exclude a developmental or cell-specific role.',
    'Inspect the underlying tissue records and consider the disease’s timing and affected cell types.', ['gene_disease', 'coverage'], source('GTEx portal documentation', 'https://gtexportal.org/home/documentationPage')),
  species: guide('Species & experimental models', 'Workspaces', 'Which organisms or models can inform follow-up work?',
    'Orthology and model-organism records help connect a human gene to related genes and available experimental systems.',
    'Check the orthology relationship, organism, phenotype and intervention. A gene deletion experiment and a specific missense substitution address different questions.',
    'A phenotype in another organism does not prove the effect of the human variant. Sequence conservation alone does not establish functional equivalence.',
    'Follow the model’s source record and verify the allele, assay and phenotype before using it as supporting evidence.', ['gene_disease', 'conservation'], source('Alliance of Genome Resources', 'https://www.alliancegenome.org/')),
  predictors: guide('Reading computational predictors', 'Workspaces', 'What do the prediction scores say about this substitution?',
    'Predictors estimate aspects of variant impact from sequence, evolutionary history, annotations or structural information.',
    'Read each score on its own scale. Published calibrated bands appear separately from author classifications and local marks; the rule trace identifies the tools actually counted.',
    'Scores are not interchangeable probabilities. A predictor’s label is not a diagnosis, and shared features can make agreement dependent.',
    'Inspect the source records, calibrated reference and any disagreement with the engine’s recorded vote.', ['evidence_strength', 'revel', 'am', 'cadd', 'conservation'], calibration),
  perturbation: guide('Sequence preference & local perturbation', 'Workspaces', 'How do models read this substitution, and what changes in the modelled neighbourhood?',
    'This workspace separates language-model preferences, changes in numerical representations and physical readings from modelled coordinates.',
    'Read sequence preference within each served model. For coordinate or energy readings, identify the paired structures and the quantity that was actually computed.',
    'Embedding drift is not atomic movement. Language-model scores are not averaged into a physical disruption score, and a rigid backbone cannot reveal a backbone response.',
    'Compare the native and alternate residue within one model, then inspect local structural readings and their availability.', ['llr', 'mutant_rank', 'embedding_shift', 'rmsd', 'foldx']),
  structure_guide: guide('Reading the 3D view', 'Workspaces', 'What can I learn from the shapes and colours?',
    'The viewer lets you inspect the selected structure, residue environment and paired models. Coordinates can come from a prediction, an experiment or local modelling.',
    'Check the structure source and colour key first. Rotate by dragging and zoom with the wheel or pinch. Selecting a residue explores the structure without changing the analysed variant.',
    'A visible difference is conditional on the method and alignment. FoldX fixes the backbone; independently predicted structures can differ for reasons other than the substitution.',
    'Use the inspector to identify the source, numbering, paired reference and confidence before interpreting contacts or displacements.', ['plddt', 'bfactor', 'pae', 'foldx', 'esmfold', 'variant_identity'], af),
  residue: guide('Residue properties & pockets', 'Workspaces', 'What chemical properties change at this position?',
    'A substitution changes the amino acid’s chemical properties. The surrounding model supplies context such as solvent accessibility and nearby predicted pockets.',
    'Compare native and alternate properties on their named scales. Read measured accessibility separately from contact counts and pocket distance.',
    'A chemical difference alone does not establish loss of function. A predicted pocket nearby does not demonstrate altered binding affinity.',
    'Inspect the local environment and pocket source, then compare with functional annotations.', ['residue_properties', 'burial_status', 'contact_density', 'p2rank']),
  residue_properties: guide('Amino-acid properties', 'Metrics', 'What does changing size, charge or hydrophobicity imply?',
    'Property scales describe different aspects of an amino acid, such as side-chain size or preference for water versus a non-polar environment.',
    'Read the named scale and compare both residues. Charge depends on chemical context, including pH; hydrophobicity scales need not use the same range or orientation.',
    'A property change suggests a question to investigate, not a measured energetic or clinical effect. The same substitution can behave differently at different sites.',
    'Inspect accessibility, contacts and functional annotations at the mapped residue.', ['burial_status', 'ddg', 'function'], source('Amino-acid index database', 'https://www.genome.jp/aaindex/')),
  function: guide('Functional domains & annotations', 'Workspaces', 'Does this position overlap a known feature?',
    'Domain, site and region annotations describe protein features associated with sequence intervals or particular residues.',
    'Read the feature’s bounds, source and evidence type. Overlapping annotations can describe related signatures, rather than separate independent findings.',
    'Being inside a domain does not establish that this substitution disrupts it or qualifies for a clinical criterion.',
    'Inspect the exact overlapping feature and the recorded PM1 trace, if present.', ['variant_identity', 'evidence_strength', 'residue'], interpro),
  hotspots: guide('Mutational hot spots', 'Workspaces', 'Is this residue in a germline mutational hot spot?',
    'A hot spot is a stretch of protein where disease-causing missense changes gather and benign ones do not. There is no single definition: expert panels name hot spots for their own genes, and several published methods estimate them from variant databases.',
    'Read each definition on its own row with its grade. An expert panel’s rule outranks a statistic; a calibrated reading outranks a method that was not validated on today’s data. Agreement between independent rows is informative; one row alone is not a verdict. The residue table adds three measurements for each ClinVar pathogenic residue, none of them a verdict: its accessibility on the AlphaFold monomer (which overstates exposure where chains meet), the UniProt sites annotated there with their evidence level, and the native solved interfaces that place it at a contact.',
    'Population depletion, clustering and enrichment are not the same as a functional consequence, and none of them is applied as PM1 here. A negative row can reflect too little data rather than tolerance.',
    'Open the expert panel’s text when one exists; otherwise read the calibrated regional row and the measured distribution, then look at the residue in 3D.', ['hotspot_cspec', 'hotspot_regional', 'hotspot_per', 'hotspot_spatial', 'function'], source('ClinGen variant curation SOP: PM1', 'https://www.clinicalgenome.org/docs/variant-curation-sop/')),
  hotspot_cspec: guide('ClinGen expert panel rules (CSpec)', 'Hot spots', 'Has an expert panel defined hot spots for this gene?',
    'ClinGen Variant Curation Expert Panels publish gene-specific versions of the ACMG/AMP criteria in the Criteria Specification Registry. For PM1 they may list residues, domains or a counting rule, and they set its strength.',
    'Only a released specification is in use. Read the PM1 text verbatim: it names the residues, domains or databases the panel accepts, and the strength each earns.',
    'The registry text is shown as written and is not parsed, because some panels publish residue tables as images. A gene without a panel has no expert hot-spot definition; that is not evidence that none exists.',
    'Follow the link to the panel’s specification and check whether this residue is named.', ['hotspots', 'evidence_strength'], source('ClinGen Criteria Specification Registry', 'https://cspec.genome.network/cspec/ui/svi/')),
  hotspot_regional: guide('Regional missense constraint (PP2 band)', 'Hot spots', 'Is this stretch of the protein depleted of missense variation in healthy people?',
    'gnomAD splits each transcript into intervals and compares the missense variants observed in about 730,000 exomes with the number expected. Chao et al. calibrated the observed/expected ratio of the interval holding a variant against ClinVar, as ClinGen recommends.',
    'O/E ≤ 0.36 reaches PP2 Moderate and ≤ 0.59 PP2 Supporting; above 0.97 and 1.23 are their BP1 bands. This app applies PP2 from this reading and does not apply BP1, which needs the gene’s curated disease mechanism.',
    'Depletion of population variation is not a cluster of pathogenic variants, so it is PP2 here, not PM1. A gene with one interval cannot rank residues within it. The calibration is a preprint.',
    'Read the interval and its O/E on the Hotspots view, and the engine record beside it.', ['constraint', 'hotspots', 'evidence_strength'], source('Chao et al., regional missense constraint (bioRxiv)', 'https://doi.org/10.1101/2024.04.11.588920')),
  hotspot_per: guide('Pathogenic-enriched regions (PER)', 'Hot spots', 'Do disease variants concentrate here more than population variants?',
    'Pérez-Palma et al. slid a 9-residue window along each protein and asked, with a Fisher exact test, whether ClinVar and HGMD disease variants fall inside it more often than gnomAD variants. Pooling paralogous genes gave the test more power.',
    'A published region lists the residues that passed after Bonferroni correction on 2019 data. The same test re-run on today’s ClinVar and gnomAD is shown separately and is not validated.',
    'gnomAD now carries missense at most residues of most genes, so the re-run seldom finds a region; a negative is not evidence of tolerance. The published regions predate later ClinVar submissions.',
    'Use a published region as support beside the expert and calibrated rows, not instead of them.', ['hotspots', 'hotspot_regional'], source('Pérez-Palma et al. 2020, Genome Research', 'https://doi.org/10.1101/gr.252601.119')),
  hotspot_spatial: guide('3D proximity to pathogenic residues (PathProx)', 'Hot spots', 'Is this residue close in 3D to known pathogenic residues?',
    'Sivley et al. tested whether pathogenic missense residues are closer together in a protein structure than expected, then scored each residue by the share of pathogenic residues within a distance minus the share of population-variant residues.',
    'The score is shown only when the clustering tests pass for this protein. Positive means more pathogenic than population neighbours, in proportion. The distance is chosen per protein where the two sets differ most.',
    'It is computed on an AlphaFold model, using confident residues only, with the residue’s own variants left out. In this app’s pre-registered benchmark it separated P/LP from gnomAD missense in several genes, but added nothing to regional O/E where O/E varies along the gene. It is a suggestion, never an ACMG criterion.',
    'Look at the residue and its nearest pathogenic neighbours in the 3D view, and read the benchmark record.', ['hotspots', 'plddt', 'structure_guide'], source('Sivley et al. 2018, Am J Hum Genet', 'https://pubmed.ncbi.nlm.nih.gov/29455857/')),
  splicing: guide('RNA splicing', 'Workspaces', 'Could this genomic change alter RNA processing?',
    'Splicing predictors assess changes in recognition of RNA splice sites. A protein-level missense annotation does not rule out an RNA effect.',
    'Read acceptor and donor gains and losses separately, together with their positions, transcript and strand. A maximum score summarises several possible events.',
    'A predicted splice effect does not establish the actual transcript product or its abundance. Missing position information limits where a signal can be drawn.',
    'Inspect the event records and transcript geometry; use RNA evidence when available to evaluate the predicted effect.', ['spliceai', 'dbscsnv', 'variant_identity'], source('SpliceAI method and outputs', 'https://github.com/Illumina/SpliceAI')),
  interfaces: guide('Interfaces & protein interactions', 'Workspaces', 'Is there evidence that this region participates in an interaction?',
    'Structure-based contacts describe a particular assembly. Interaction databases describe associations supported by different experiments or predictions.',
    'Read which chains or partners are involved, the contact definition, assembly source and evidence channel. A database confidence score belongs to that source’s association model.',
    'An association is not necessarily a direct physical interaction. A contact near the variant does not quantify a change in binding affinity.',
    'Inspect the assembly and partner records, distinguishing mapped contacts from broader gene-level associations.', ['interface_contacts', 'string', 'boltz2', 'ddmut_ppi', 'variant_identity'], source('STRING evidence channels', 'https://string-db.org/help/faq/')),
  interface_contacts: guide('Interface contacts', 'Metrics', 'What does a contact at this residue demonstrate?',
    'A contact is a geometric relationship between atoms or residues in the structure and assembly being examined.',
    'Check the chains, atom selection, distance rule and residue mapping. Contact counts and counts of interface residues use different denominators.',
    'Distance alone does not measure interaction energy or the change caused by a mutation. A monomer cannot reveal every biologically relevant assembly interface.',
    'Inspect the assembly source and mapped contacts, then seek interaction-specific experiments if the mechanism matters.', ['interfaces', 'ddg'], source('RCSB PDB: biological assemblies', 'https://pdb101.rcsb.org/learn/guide-to-understanding-pdb-data/biological-assemblies')),
  boltz2: guide('Boltz-2 complex prediction', 'Structure methods', 'What does a predicted protein assembly tell me?',
    'The Interfaces workspace uses Boltz-2 to predict a candidate complex from the specified chains and sequences.',
    'Inspect the chain identities, the chain carrying the variant, the returned confidence and mapped contacts. The binding-change estimate is a separate DDMut-PPI calculation on a wild-type complex.',
    'A predicted contact is not an observed interaction or proof that the variant lost a native contact. A model capability described in a paper does not establish which operation this run performed.',
    'Check the served-model record and compare with solved assemblies for the same protein and biological context.', ['iptm', 'interface_contacts', 'ddmut_ppi', 'model_provenance'], source('Boltz methods and outputs', 'https://github.com/jwohlwend/boltz')),
  iptm: guide('ipTM & pTM confidence', 'Structural metrics', 'How confident is the model in the assembled structure?',
    'Interface predicted TM-score (ipTM) estimates confidence in relative subunit placement; predicted TM-score (pTM) describes overall structural arrangement.',
    'Higher scores indicate greater model confidence. Read the scope: an aggregate interface score can hide variation between individual interfaces. The displayed reference bands come from AlphaFold-Multimer guidance.',
    'Confidence is not binding affinity or a probability of disease. Applying AlphaFold-Multimer reference marks to a Boltz-2 result does not establish a Boltz-specific calibration.',
    'Inspect the contacts, chain pair and local or relative-position confidence before interpreting the model.', ['boltz2', 'pae', 'plddt'], source('EMBL-EBI: AlphaFold-Multimer confidence', 'https://www.ebi.ac.uk/training/online/courses/alphafold/inputs-and-outputs/evaluating-alphafolds-predicted-structures-using-confidence-scores/confidence-scores-in-alphafold-multimer/')),
  ddmut_ppi: guide('DDMut-PPI binding change', 'Interaction methods', 'Does the model predict weaker or stronger protein binding?',
    'DDMut-PPI predicts how an amino-acid substitution changes protein-protein binding affinity using a wild-type complex structure.',
    'Read the result in kcal/mol using the DDMut-PPI convention: negative means weaker binding, positive means stronger binding. Check whether the wild-type input is solved or predicted.',
    'The benchmark error band describes performance over a test set, not a confidence interval for this variant. This is a prediction of binding change, distinct from protein folding stability and from clinical classification.',
    'Verify the partner, assembly and mutation mapping, then compare with interaction-specific experimental evidence.', ['boltz2', 'interface_contacts', 'ddg', 'uncertainty'], source('Zhou et al. DDMut-PPI (2024)', 'https://doi.org/10.1093/nar/gkae412')),
  string: guide('STRING association scores', 'Sources', 'Does a high STRING score mean strong binding?',
    'STRING scores confidence in a protein association using several evidence channels, including experiments, curated databases and computational signals.',
    'Read the contributing channels and whether the record describes functional association or physical interaction.',
    'The score is not binding affinity, and a gene-level association is not variant-specific evidence of disruption.',
    'Open the source evidence and compare it with mapped structural contacts.', ['interfaces', 'interface_contacts'], source('STRING FAQ', 'https://string-db.org/help/faq/')),
  energetics: guide('Stability & energetics', 'Workspaces', 'Do the available methods predict a change in protein stability?',
    'Stability methods estimate how a substitution changes the energetic preference for the folded protein relative to the reference.',
    'The comparison uses a common displayed sign: positive means destabilizing. Read the original source convention, units, per-engine marks and usable-engine count in the records.',
    'Stability is one possible mechanism. Engine agreement is descriptive and is not a probability of disease or misfolding.',
    'Inspect the individual estimates, input structure and disagreement before interpreting the summary.', ['ddg', 'foldx', 'uncertainty', 'model_disagreement']),
  ddg: guide('ΔΔG · stability change', 'Metrics', 'What does a positive or negative energy change mean?',
    'Delta-delta G compares a variant’s predicted folding stability with the reference. It is commonly reported in kilocalories per mole (kcal/mol).',
    'In the app’s normalized stability comparison, positive values mean destabilizing and negative values stabilizing. Some providers use the reverse sign; read the labelled source value before comparing it.',
    'A value near zero is not proof of no effect, and energy components are not the total stability estimate. Numerical prediction uncertainty may be larger than a small difference.',
    'Check the source convention, local display marks and method limitations, then compare available engines.', ['energetics', 'uncertainty', 'vdw', 'electrostatics']),
  landscape: guide('Mutation landscape', 'Workspaces', 'Which substitutions stand out across the protein?',
    'A landscape arranges scores by position and alternate amino acid so you can explore patterns across many candidate substitutions.',
    'Read the selected model, colour scale, sequence window and coverage. Hover previews a value; selecting a candidate does not itself validate its biological effect.',
    'Blank cells are unassessed, not neutral. A colour scale must retain the chosen model’s meaning and cannot make scores from different models equivalent.',
    'Inspect an individual cell, confirm its residue identity and then examine the corresponding evidence.', ['llr', 'ddg', 'variant_identity', 'coverage']),
  insights: guide('Interpreting the synthesis', 'Workspaces', 'Which conclusions are supported by this analysis?',
    'The synthesis brings together retrieved evidence and the rule engine’s recorded criteria. Narrative text explains those findings.',
    'Follow each claim back to its source or rule trace. Read whether a criterion was counted, withheld or unconfirmed and whether narrative generation completed.',
    'Fluent prose does not add evidence. A generated mechanism remains a hypothesis unless the available observations establish it.',
    'Resolve conflicting evidence and inspect the original records before carrying a statement into a report.', ['evidence_strength', 'clinical_assertions', 'report']),
  literature: guide('Literature evidence', 'Workspaces', 'Does this publication actually support a claim about the variant?',
    'A search retrieves candidate papers. Relevance depends on what the paper studied and what evidence it reports.',
    'Distinguish a gene mention, exact variant match, abstract match and verified full-text evidence. Read the query and any incomplete or failed search stages.',
    'Search relevance and publication counts are not evidence strength. A mention does not establish an experimental finding, and an empty search does not establish absence from the literature.',
    'Open the paper, verify the allele and assay, and record the specific supported claim.', ['variant_identity', 'evidence_strength', 'report'], source('PubMed search guide', 'https://pubmed.ncbi.nlm.nih.gov/help/')),
  report: guide('Reports & exported evidence', 'Workspaces', 'What should remain visible when I share the interpretation?',
    'A useful report preserves the analysed variant, supporting observations, recorded criteria, limitations and sources alongside the author’s interpretation.',
    'Review source dates, structure/model provenance, missing evidence and author edits. Check the export description: a full evidence bundle can include more than the visible report sections.',
    'Exporting or rewriting a statement does not increase its evidential strength. An AI narrative and a source-backed assertion must remain distinguishable.',
    'Verify the final document against the source records and retain its provenance manifest.', ['variant_identity', 'model_provenance', 'evidence_strength']),
  am: guide('AlphaMissense', 'Predictors', 'How does AlphaMissense assess this amino-acid substitution?',
    'AlphaMissense estimates missense variant impact using learned sequence and structural information.',
    'Higher scores indicate a stronger predicted deleterious effect. Read the author classification separately from the published calibrated evidence bands shown in the predictor records.',
    'The score does not identify an atomic mechanism, measure stability, or provide a final clinical diagnosis.',
    'Inspect the calibrated band and recorded engine contribution, alongside other evidence.', ['predictors', 'evidence_strength', 'ddg']),
  cadd: guide('CADD PHRED', 'Predictors', 'What does a high CADD rank tell me?',
    'CADD combines annotations into a relative deleteriousness score. The PHRED form expresses a rank among possible substitutions.',
    'Higher PHRED scores indicate a more extreme rank. Use the displayed calibrated bands for the clinical evidence reading, rather than treating a percentile as a probability.',
    'A high rank is not the chance that the variant causes disease or a measurement of physical damage.',
    'Check the score type and calibrated reference in the predictor records.', ['percentile', 'evidence_strength']),
  revel: guide('REVEL', 'Predictors', 'What does the ensemble predict for this missense variant?',
    'REVEL combines multiple predictor inputs into one missense impact score.',
    'Higher values favour a deleterious prediction. Read the published evidence-strength bands and the rule engine’s actual use of this score.',
    'Its component predictors are not independent confirmations of REVEL. The score alone is not a clinical classification.',
    'Compare the calibrated reading with independent population, clinical and functional evidence.', ['predictors', 'evidence_strength', 'model_disagreement']),
  bayesdel: guide('BayesDel without allele frequency', 'Predictors', 'What does this combined predictor add?',
    'BayesDel integrates other predictive annotations. The noAF version used here omits an allele-frequency feature.',
    'Higher values favour a deleterious prediction. Use the noAF calibration and verify which version supplied the record.',
    'Omitting allele frequency does not make all inputs independent of other predictors or eliminate every source of overlap.',
    'Read the calibrated band and inspect the recorded contribution.', ['model_provenance', 'evidence_strength']),
  eve: guide('EVE', 'Predictors', 'How compatible is the substitution with an evolutionary sequence family?',
    'EVE learns patterns of amino-acid variation from related protein sequences to estimate variant effects.',
    'Read the returned EVE score and any source classification together. Sequence-family information supplies evolutionary context.',
    'A model class does not establish a clinical classification or a physical mechanism. Do not invent universal cut-points when none are supplied for the reading.',
    'Check source coverage and compare the result with independent evidence.', ['conservation', 'popeve']),
  popeve: guide('popEVE', 'Predictors', 'How unusual is this substitution on a proteome-wide evolutionary scale?',
    'popEVE combines evolutionary models and human population information to place variant scores on a scale intended for comparison across proteins.',
    'More negative values indicate a stronger predicted deleterious effect. The displayed author thresholds describe deleterious categories.',
    'Being above a deleterious threshold is not a benign call. Population information in the model can overlap with separate frequency evidence.',
    'Read the source interpretation and compare with gene–disease context and population records.', ['eve', 'population', 'evidence_strength']),
  metarnn: guide('MetaRNN', 'Predictors', 'What does this annotation ensemble predict?',
    'MetaRNN combines predictor and conservation features with population frequency information.',
    'Higher scores favour the model’s deleterious class. Its author operating point is distinguished from calibrated clinical evidence bands.',
    'Population features overlap with frequency evidence; ClinVar training can overlap with existing clinical assertions.',
    'Check the engine trace and avoid treating correlated inputs as independent corroboration.', ['model_disagreement', 'population', 'clinical_assertions']),
  clinpred: guide('ClinPred', 'Predictors', 'What does a model trained on clinical labels predict?',
    'ClinPred combines predictive annotations and allele-frequency information to distinguish training examples labelled benign or pathogenic.',
    'Higher scores favour its pathogenic class. Read the author’s class separately from the app’s recorded clinical assessment.',
    'A ClinVar-trained prediction can overlap with ClinVar assertions, and frequency features overlap with population evidence.',
    'Inspect the source data and recorded contribution before combining evidence.', ['clinical_assertions', 'population', 'model_disagreement']),
  eigen: guide('Eigen / Eigen-PC', 'Predictors', 'What do combined functional annotations suggest?',
    'Eigen combines annotations without using clinical labels as a supervised training target.',
    'Check whether the returned value is a raw score or a PHRED-scaled rank. Higher values favour a stronger functional-effect signal on the corresponding scale.',
    'This is not a calibrated disease probability, and PHRED ranks are not interchangeable with raw scores.',
    'Read the source scale and informational role in the predictor records.', ['percentile', 'predictors']),
  dann: guide('DANN', 'Predictors', 'What does the annotation-based neural network predict?',
    'DANN uses a neural network to combine variant annotations into a score of predicted deleteriousness.',
    'Higher scores indicate a stronger model signal. This app presents the reading as informational.',
    'A score between zero and one is not automatically a calibrated probability of disease.',
    'Compare the source reading with calibrated predictors and independent evidence.', ['predictors', 'evidence_strength']),
  conservation: guide('Evolutionary conservation', 'Metrics', 'Has this position changed little during evolution?',
    'Conservation methods examine how sequence positions vary across related organisms. Constraint can suggest that a position has a biological role.',
    'Read the alignment, species coverage and method-specific scale. Different conservation scores measure different departures from evolutionary expectations.',
    'Conservation does not identify a specific disease mechanism. A conserved position can tolerate some substitutions and not others.',
    'Inspect the particular substitution and its molecular context, rather than assigning a verdict from conservation alone.', ['phylop', 'gerp', 'consurf', 'species']),
  phylop: guide('phyloP', 'Predictors', 'Is evolution unusually slow or fast at this nucleotide?',
    'phyloP compares observed substitutions with a neutral evolutionary model.',
    'Positive scores indicate conservation and negative scores acceleration. Use the matching published bands where the app supplies a calibrated reading.',
    'A nucleotide conservation score does not directly measure protein stability or the effect of a particular amino-acid change.',
    'Check alignment context and the engine trace.', ['conservation', 'evidence_strength'], source('PHAST / phyloP', 'https://github.com/CshlSiepelLab/phast')),
  gerp: guide('GERP++', 'Predictors', 'How much expected sequence change appears to have been prevented?',
    'GERP++ measures evolutionary constraint using the difference between expected and observed substitutions.',
    'Higher positive scores indicate more rejected substitutions. Read the available calibrated bands without inventing a pathogenic band where none is provided.',
    'Constraint at a site is not a variant-specific mechanism or a clinical classification.',
    'Inspect the calibrated reference and other variant-level evidence.', ['conservation', 'evidence_strength'], calibration),
  consurf: guide('ConSurf', 'Predictors', 'How conserved is this amino-acid position in its sequence family?',
    'ConSurf estimates evolutionary conservation at protein positions from an alignment of related sequences.',
    'Read the conservation grade, alignment coverage and any uncertainty or insufficient-data flag.',
    'A conservation grade is not a disease probability. Its quality depends on which homologues and positions were aligned.',
    'Inspect the position’s structural and functional context.', ['conservation', 'function'], source('ConSurf documentation', 'https://consurf.tau.ac.il/')),
  esm1b: guide('ESM-1b', 'Sequence models', 'How does the sequence model score this substitution?',
    'ESM-1b learns patterns in protein sequences and scores how expected an alternate residue is relative to the native residue.',
    'More negative log-likelihood ratios favour the native residue. Use the ESM-1b-specific calibration shown by the app; it does not apply to ESM-2 or ESM C.',
    'A model-native preference is not an energy change. Calibrations are specific to the tool and scoring method.',
    'Confirm the served score identity and inspect its evidence band.', ['llr', 'model_provenance', 'evidence_strength'], source('Additional computational-tool calibration', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12208618/')),
  esm2: guide('ESM-2', 'Sequence models', 'Which residue does this protein language model expect here?',
    'ESM-2 learns sequence patterns from proteins and compares the alternate residue with the native residue in that context.',
    'Read the log-likelihood ratio and residue distribution within the returned model. A negative ratio favours the native residue.',
    'Sequence preference is not a stability estimate or a measurement of atomic movement. ESM-1b clinical thresholds must not be reused for ESM-2.',
    'Check the served model and compare its native and alternate probabilities.', ['llr', 'mutant_rank', 'entropy', 'model_provenance']),
  esmc: guide('ESM C', 'Sequence models', 'What does ESM C infer from the protein sequence?',
    'ESM C is a protein language model that returns sequence representations and, in this workflow, residue preferences.',
    'Read the served model in the record. The ESM C slot can be supplied by a VESM fallback; each score retains its own model’s scale.',
    'An embedding difference is a change in model representation, not a physical displacement or a clinical probability.',
    'Inspect the returned model name, residue probabilities and any fallback reason.', ['vesm', 'llr', 'embedding_shift', 'model_provenance'], source('ESM C model documentation', 'https://github.com/evolutionaryscale/esm')),
  vesm: guide('VESM', 'Sequence models', 'How should I interpret the smaller fallback model?',
    'VESM is a compact protein language model. It can supply sequence scores when used as the local alternative in this workflow.',
    'Read its log-likelihood ratio within VESM and identify the served model in the record. A fallback can be useful while remaining a distinct method.',
    'A VESM result must not inherit ESM C’s identity or presumed calibration. A different model size does not establish the reliability of this individual prediction.',
    'Inspect the fallback reason and compare native and alternate preferences within the same model.', ['esmc', 'llr', 'model_provenance']),
  saprot: guide('SaProt', 'Sequence models', 'What does adding structural context change about sequence preference?',
    'SaProt combines amino-acid identity with tokens describing local structure to learn sequence preferences in structural context.',
    'Read the served model and whether structure tokens were available. A missing structure token means the result lacks that part of the intended context.',
    'Its likelihood is not a physical energy. Input structure errors or missing tokens limit what can be inferred from the score.',
    'Inspect the structure-token status, distribution and native-versus-alternate preference.', ['llr', 'entropy', 'model_provenance']),
  gpn_star: guide('GPN-Star', 'Sequence models', 'How expected is this nucleotide in an evolutionary alignment?',
    'GPN-Star uses genomic sequence alignments and phylogenetic information to model nucleotide preferences.',
    'A more negative alternate-versus-reference log-likelihood ratio means the alternate base is less expected by the model. Local reference marks are not clinical evidence bands.',
    'This is a nucleotide-level constraint signal, not a coordinate prediction or a physical energy calculation.',
    'Verify genomic identity and alignment coverage before comparing with protein-level evidence.', ['llr', 'conservation', 'variant_identity']),
  llr: guide('Log-likelihood ratio · LLR', 'Metrics', 'How much does the model favour the alternate residue over the native one?',
    'The ratio compares the model’s probability for the alternate residue with its probability for the native residue. The natural logarithm expresses that ratio in nats.',
    'For log(P(alternate)/P(native)), negative favours native, positive favours alternate and zero means equal probabilities. Compare magnitudes within the same model and scoring method.',
    'These are model probabilities for residues, not probabilities of disease. Averaging LLRs from different model families does not produce a calibrated impact score.',
    'Inspect both probabilities and the distribution, especially when the model gives little preference to any residue.', ['mutant_rank', 'entropy', 'model_provenance'], esm),
  mutant_rank: guide('Residue rank & probability', 'Metrics', 'Does a high-ranked alternate residue mean the substitution is tolerated?',
    'Rank orders the candidate amino acids within one model’s distribution. It says where a residue sits, not how far apart its probability is from the others.',
    'Compare alternate rank and probability with the native residue. The alternate can rank second while remaining much less probable than native.',
    'Rank is not a probability of tolerance or a clinical verdict. A nearly flat distribution offers little preference even though it still has an ordering.',
    'Read the native-versus-alternate ratio and distribution together.', ['llr', 'entropy'], esm),
  entropy: guide('Residue-distribution entropy', 'Metrics', 'Is the model expressing a strong preference at this position?',
    'Entropy describes how spread out the model’s probabilities are across amino acids.',
    'Read entropy in bits. Lower entropy means probability is concentrated on fewer candidates; higher entropy means the distribution is flatter. Read any flatness mark as an app-defined interpretation aid.',
    'A concentrated distribution is not proof that the model is correct, and a flat distribution is not proof that every substitution is harmless.',
    'Inspect the full distribution before interpreting a rank or preference.', ['mutant_rank', 'llr'], esm),
  embedding_shift: guide('Embedding drift', 'Metrics', 'Did the model’s numerical representation change?',
    'An embedding is a vector of numbers learned by a model. Comparing vectors before and after a substitution describes a change in that representation.',
    'Read the distance definition, model, sequence window and position of the peak. Euclidean and cosine distances use different scales and are not interchangeable.',
    'Embedding distance has no unit of angstroms and is not observed motion, allostery or binding energy. A peak away from the site does not by itself establish a remote biological effect.',
    'Check the model-specific metric and residue mapping; use coordinate evidence for physical geometry questions.', ['esm3', 'llr', 'rmsd']),
  vesm_embedding: guide('VESM embedding analysis', 'Sequence models', 'What did the fallback model actually measure?',
    'This result compares VESM representations of the native and alternate sequences. VESM supplied the calculation requested through the ESM3 service slot.',
    'The displayed value is cosine distance between embeddings, not a log-likelihood ratio. Read the recorded model, covered sequence window, variant-site distance and location of the peak. Unscored positions are missing, not zero.',
    'The distance is unitless. It does not measure physical motion, binding energy or disease probability. The app-defined bands are not a validated clinical calibration and cannot establish equivalence with ESM3.',
    'Check the fallback provenance and coverage before comparing runs. Use coordinate measurements for structural geometry.', ['embedding_shift', 'model_provenance', 'coverage'], source('VESM methods', 'https://doi.org/10.1038/s41592-026-03050-9')),
  esm3: guide('ESM3 representation analysis', 'Sequence models', 'Is this result a generated structure or an embedding comparison?',
    'ESM3 supports multiple kinds of protein modelling. The representation analysis shown here compares sequence embeddings.',
    'Read the actual operation and provenance. An embedding drift value belongs to the representation analysis; an input structure confidence value belongs to that input.',
    'A method’s ability to generate structures does not mean generation ran. Embedding drift cannot demonstrate backbone movement.',
    'Inspect the operation recorded for the result and follow any coordinate result separately.', ['embedding_shift', 'model_provenance', 'plddt'], source('ESM3 methods and SDK', 'https://github.com/evolutionaryscale/esm')),
  foldx: guide('FoldX', 'Stability methods', 'What changed after local side-chain modelling?',
    'FoldX models a substitution and repacks side chains on the template backbone, then estimates energy differences.',
    'Read the total ΔΔG separately from its energy components. Compare the variant with its paired reference and check whether template repair succeeded.',
    'The backbone is fixed: zero backbone displacement does not establish that the real protein cannot move. Repeated-run spread measures repeatability, not total prediction error.',
    'Inspect the structure source, repair status, total estimate and side-chain comparison.', ['ddg', 'rmsd', 'vdw', 'uncertainty']),
  dynamut2: guide('DynaMut2', 'Stability methods', 'What stability change does this structure-based model predict?',
    'DynaMut2 combines structural and flexibility-related information to estimate a substitution’s effect on stability.',
    'The provider’s sign is reversed in the common stability comparison so positive means destabilizing. Read the displayed units and local marks.',
    'The estimate is not an observed trajectory or an experimental stability measurement.',
    'Inspect the input structure and compare with other available stability estimates.', ['ddg', 'model_disagreement']),
  ddmut: guide('DDMut', 'Stability methods', 'What stability change does this learned structural method predict?',
    'DDMut learns relationships between structural features, substitutions and changes in protein stability.',
    'The app normalizes the provider’s sign for comparison: positive displayed ΔΔG means destabilizing. Source records retain the method context.',
    'Benchmark performance does not give an error bar for this individual variant. Clinical pathogenicity is a separate question.',
    'Check structural coverage and disagreement with other methods.', ['ddg', 'uncertainty']),
  rasp: guide('RaSP', 'Stability methods', 'What does this precomputed stability estimate represent?',
    'RaSP learns to approximate Rosetta stability calculations from local structural environments. This app retrieves precomputed values.',
    'Positive values mean destabilizing in the common comparison. Check the dataset and whether the queried protein and residue are covered.',
    'It inherits limitations of the calculations it approximates. A missing table entry is not a neutral prediction.',
    'Inspect coverage and source structure before comparing with newly computed estimates.', ['ddg', 'coverage']),
  protvar: guide('ProtVar FoldX', 'Stability methods', 'What does the ProtVar FoldX value add to the FoldX run here?',
    'EBI ProtVar precomputes FoldX ΔΔG for every substitution on the AlphaFold DB model of the canonical sequence. This app retrieves that value.',
    'It is FoldX on EBI’s AlphaFold model, not necessarily on this run’s template. The two values differ in template and in pipeline (repair, runs, settings), so a gap of about 1 kcal/mol or more shows how template-sensitive FoldX is for this variant; it is not an error bar on either value, and a sign difference matters more than the size. Positive means destabilizing.',
    'It is the same method as FoldX, so it is never counted as a second engine. It counts as the FoldX reading only when no local FoldX value exists and the template is the AlphaFold model. Where the AlphaFold model has low pLDDT at the residue the estimate is unreliable, and long proteins split into fragment models can disagree, in which case no value is shown.',
    'Compare it with the local FoldX value and read the pLDDT note before relying on either.', ['ddg', 'model_provenance'],
    source('Stephenson et al. Nucleic Acids Res (2024)', 'https://doi.org/10.1093/nar/gkae413')),
  thermompnn: guide('ThermoMPNN', 'Stability methods', 'What stability effect does the learned structural representation predict?',
    'ThermoMPNN uses protein structural representations to predict the effect of an amino-acid substitution on stability.',
    'Positive displayed ΔΔG means destabilizing. Read the returned input and provenance, together with the app-defined comparison marks.',
    'A learned estimate remains conditional on its training distribution and input structure. It does not measure binding affinity or disease risk.',
    'Inspect the method record and compare the available estimates.', ['ddg', 'model_provenance']),
  stabilityoracle: guide('StabilityOracle', 'Stability methods', 'Does the structural model predict a stabilizing or destabilizing change?',
    'StabilityOracle uses a learned structural representation to predict stability effects of substitutions.',
    'Negative values favour stabilization and positive values destabilization on the displayed comparison scale. Local marks describe the app’s reading.',
    'A stabilizing substitution can still affect function. Stability direction alone cannot establish a benign clinical effect.',
    'Compare the estimate with functional context and other stability methods.', ['ddg', 'function']),
  rmsd: guide('Neighbour side-chain RMSD', 'Structural metrics', 'How different are nearby modelled side-chain positions?',
    'Root-mean-square deviation (RMSD) summarises distances between matched atoms after fitting the structures. Here it describes side chains within ±5 of the site, compared with the paired wild type.',
    'Read the atom selection, local window and paired reference. The value is in angstroms (Å); larger values mean a larger coordinate difference for those matched atoms.',
    'This is a comparison of models, not observed molecular motion. Repair moves can enter the comparison when a paired repaired reference is unavailable.',
    'Inspect the structural pair and alignment; use the reported availability when too few atoms can be matched.', ['foldx', 'structure_guide', 'uncertainty']),
  vdw: guide('Van der Waals clash energy', 'Structural metrics', 'Did the modelled packing become more crowded?',
    'This FoldX energy component describes steric repulsion associated with atomic packing.',
    'A positive component change indicates a greater steric energy penalty in the model. Read the local reference mark as an app-defined aid, not a clinical threshold.',
    'One energy component is not total ΔΔG. It cannot demonstrate backbone distortion, protein misfolding or a disease mechanism.',
    'Inspect nearby side chains and the total stability estimate separately.', ['foldx', 'ddg', 'rmsd']),
  electrostatics: guide('Electrostatic energy change', 'Structural metrics', 'How did the model’s charge-interaction energy change?',
    'The electrostatic component estimates an energy contribution from charges in the modelled environment.',
    'Read the component’s sign and units relative to the paired reference, alongside the total FoldX energy.',
    'A changed component does not identify a particular broken salt bridge or hydrogen bond. Those claims require contact-specific evidence.',
    'Inspect the local geometry and conditions before proposing an interaction mechanism.', ['foldx', 'ddg', 'interface_contacts']),
  atomic_clashes: guide('Atomic clash counts', 'Structural metrics', 'Does the model contain more overlapping atoms?',
    'A clash count counts atom pairs that satisfy the calculation’s geometric overlap rule.',
    'Compare native and alternate counts using the same atom selection and clash definition. The difference is a count, while the FoldX clash term is an energy.',
    'A count does not quantify total stability or establish that the real protein adopts the modelled conformation.',
    'Inspect the actual atom pairs and distinguish a geometric count from the energy component.', ['vdw', 'foldx', 'structure_guide']),
  ca_displacement: guide('Cα coordinate displacement', 'Structural metrics', 'Did matched backbone positions differ between the structures?',
    'A displacement compares matched alpha-carbon coordinates after the stated structural alignment.',
    'Read the structure pair, fitting region, residue window and units in angstroms. A maximum and an average describe different summaries.',
    'FoldX fixes the backbone, so its zero displacement is imposed by the method. Independent folding predictions can differ without establishing a mutation-induced movement.',
    'Check whether the method permits a backbone change before interpreting the comparison.', ['structure_guide', 'foldx', 'esmfold']),
  residue_contacts: guide('Residue contact changes', 'Structural metrics', 'Which modelled neighbours were gained or lost?',
    'Contact changes compare the neighbours that meet a geometric distance rule in the native and alternate models.',
    'Read the distance definition, matched structures and counts of gained and lost contacts separately.',
    'A gained contact is not necessarily a favourable bond, and a lost contact is not necessarily destabilizing. Geometry alone does not supply interaction energy.',
    'Inspect the atoms involved and compare with the energy and accessibility readings.', ['interface_contacts', 'ddg', 'sasa']),
  contact_density: guide('Local Cα contact density', 'Structural metrics', 'How crowded is the residue’s neighbourhood?',
    `Contact density counts nearby alpha-carbon atoms within ${PACKING_NEIGHBOUR_BANDS.radiusAngstrom}Å.`,
    'Read the radius, chain context and count. This is a reading only, with no count cut-points; solvent accessibility supplies the separate burial reading.',
    'Contacts include sequence neighbours and do not establish burial, bond formation or energetic effects.',
    'Compare with measured accessibility and the local structure.', ['burial_status', 'structure_guide']),
  burial_status: guide('Solvent accessibility & burial', 'Structural metrics', 'How exposed is this residue to solvent in the model?',
    'Solvent-accessible surface area (SASA) estimates the surface reachable by a probe. Relative accessibility (RSA) compares that area with a residue-specific reference.',
    `Lower RSA means less accessible surface. App-defined bands are core ≤ ${BURIAL_RSA_BANDS.coreMax * 100}% and surface ≥ ${BURIAL_RSA_BANDS.surfaceMin * 100}%; boundary lies between. Inspect the measured RSA and source structure.`,
    'Absolute area and relative accessibility are different quantities. More accessible area after changing amino-acid size does not necessarily mean the residue became less buried.',
    'Read the area, reference normalization and structure quality together.', ['sasa', 'contact_density', 'residue_properties']),
  sasa: guide('SASA & changes in accessible area', 'Structural metrics', 'How much surface area is accessible in each model?',
    'SASA is solvent-accessible surface area, usually expressed in square angstroms (Å²). A delta compares alternate and reference areas.',
    'A positive alternate-minus-reference delta means more calculated accessible area. Compare absolute areas with relative accessibility when residue size changes.',
    'Area change does not by itself establish a change in burial, stability or binding affinity. Geometry and normalization affect the reading.',
    'Inspect the two areas, residue identities and RSA before interpreting the change.', ['burial_status', 'residue_properties'], source('Reference accessible surface areas', 'https://doi.org/10.1371/journal.pone.0080635')),
  p2rank: guide('P2Rank pockets', 'Structural metrics', 'Is there a predicted ligand-binding cavity near the residue?',
    'P2Rank identifies and ranks candidate pockets from a protein structure’s surface features.',
    'Read pocket membership, distance to the reported centre and the model profile. The pocket probability refers to a candidate binding site, not ligand affinity.',
    'A nearby pocket does not demonstrate an effect of the substitution on binding. Profile-specific probabilities are not directly comparable across profiles.',
    'Inspect the pocket residues and source structure, and seek ligand-specific evidence for a binding claim.', ['residue', 'interface_contacts']),
  plddt: guide('pLDDT · local structure confidence', 'Structural metrics', 'How confident is the model in the local coordinates?',
    'Predicted local distance difference test (pLDDT) is a per-residue estimate of local structural confidence.',
    'Higher values indicate greater model confidence. Read the canvas legend and the structure that supplied the value.',
    'High confidence does not establish functional importance or the effect of a mutation. Low confidence alone does not prove disorder.',
    'Use confidence to qualify geometric interpretations and inspect relative domain confidence separately when available.', ['pae', 'bfactor', 'structure_guide'], af),
  pae: guide('PAE · relative-position confidence', 'Structural metrics', 'How confident is the model about the placement of one region relative to another?',
    'Predicted aligned error estimates positional error for pairs of residues when the structure is aligned on one member of the pair.',
    'Read the matrix axes and units in angstroms. Lower values indicate greater confidence in relative placement.',
    'Locally confident domains can still have uncertain relative positions. A confidence map does not demonstrate a physical interaction.',
    'Check relative placement before interpreting distances across domains or chains.', ['plddt', 'interfaces'], af),
  structure_confidence: guide('Uninterpreted structure confidence', 'Structural metrics', 'Why is there no confidence reading here?',
    'A confidence reading needs coordinates at the selected residue and a known meaning for the structure file’s confidence field.',
    'Read the reason shown for this structure. Missing coordinates and an unidentified field are different states; neither supplies a confidence score.',
    'The same file column can contain pLDDT, crystallographic B-factors or other values. Unknown provenance must not be interpreted as pLDDT. Missing confidence is not low confidence.',
    'Check the coordinate source and residue mapping. Interpret the field only when its meaning is documented.', ['plddt', 'bfactor', 'model_provenance', 'missing_data']),
  bfactor: guide('Crystallographic B-factor', 'Structural metrics', 'What do these experimental structure colours represent?',
    'A crystallographic B-factor describes atomic displacement or disorder represented by a refined crystal structure model.',
    'Read the structure’s own colour key and source. Predicted structures often store pLDDT in the same file column, so the field’s meaning depends on provenance.',
    'B-factor and pLDDT are not interchangeable confidence scales. B-factors are influenced by experimental and refinement conditions.',
    'Confirm the source before interpreting colour or comparing entries.', ['plddt', 'model_provenance'], source('RCSB PDB: temperature factors', 'https://pdb101.rcsb.org/learn/guide-to-understanding-pdb-data/dealing-with-coordinates')),
  esmfold: guide('ESMFold structure prediction', 'Structure methods', 'What does an independently predicted mutant structure show?',
    'ESMFold predicts coordinates from a protein sequence. Separate native and alternate predictions provide candidate structures to explore.',
    'Inspect the aligned pair, mapped residues and confidence. Compare differences within well-supported regions.',
    'Differences include the predictions’ own variability and cannot all be attributed to mutation. These coordinates do not simulate a physical trajectory.',
    'Treat structural differences as hypotheses and compare with independent evidence.', ['structure_guide', 'plddt', 'uncertainty'], esm),
  spliceai: guide('SpliceAI', 'RNA methods', 'Which splice-site recognition signals might change?',
    'SpliceAI predicts splice-site recognition from DNA sequence. Variant delta scores describe predicted acceptor or donor gains and losses.',
    'Read each event’s score and position along with the maximum. The score is a predicted change in a splice-site probability, not the probability that the variant causes disease.',
    'The result does not establish the final RNA product. Transcript mapping, strand and available positional coverage matter.',
    'Inspect the event records and transcript geometry; compare with RNA experiments when available.', ['splicing', 'variant_identity', 'evidence_strength']),
  dbscsnv: guide('dbscSNV', 'RNA methods', 'What do the splice-region ensemble scores suggest?',
    'dbscSNV provides AdaBoost and random-forest predictions for substitutions in splice-site consensus regions.',
    'Read the Ada and RF scores and their source coverage. The author operating point is labelled separately from clinical evidence calibration.',
    'An absent score outside the covered region provides no evidence against a splice effect. The two scores are related models, not two independent experiments.',
    'Check the variant’s position relative to the splice site and compare with broader sequence-context predictions.', ['splicing', 'spliceai', 'coverage']),
  alphagenome: guide('AlphaGenome AVI', 'Regulatory methods', 'What does the genome-wide impact ranking suggest?',
    'The Atlas AVI score combines variant features into a genome-wide impact ranking; its attributions show how reported features contribute to the raw score.',
    'Read raw AVI, PHRED rank and feature contributions as separate quantities. A positive contribution increases raw AVI; it does not specify whether expression or disease risk increased.',
    'AVI PHRED is not a clinical probability. Features include protein and conservation signals, so it cannot be treated as independent of all other predictors.',
    'Inspect attribution coverage and the contributing feature families before proposing a regulatory mechanism.', ['percentile', 'shap', 'coverage', 'am'], source(ALPHAGENOME_SOURCES[0].citation, `https://doi.org/${ALPHAGENOME_SOURCES[0].doi}`)),
  percentile: guide('Ranks, percentiles & PHRED scales', 'Metrics', 'Does a top-percentile score mean a high probability of disease?',
    'A percentile locates a value within a reference distribution. PHRED-like transformations can make extreme ranks easier to display.',
    'Check the reference population and the specific score definition. CADD and AVI ranks describe their own scoring systems and reference sets.',
    'A rank says how unusual a score is, not how likely a diagnosis is. The same displayed PHRED value need not describe the same biological effect in different tools.',
    'Read any clinical evidence calibration separately.', ['cadd', 'alphagenome', 'evidence_strength']),
  shap: guide('Feature contributions · SHAP', 'Metrics', 'Which inputs contributed to this model score?',
    'Feature attributions allocate changes in a model output relative to a reference. They help explain the model’s calculation.',
    'Read the sign as movement of the named output. Contribution shares describe reported absolute attribution magnitude; check whether all features were returned.',
    'Attribution is not causation, a percentage of disease risk, or necessarily the biological direction of a feature’s effect.',
    'Inspect the feature definition and coverage, then consult the underlying evidence for biological interpretation.', ['alphagenome', 'coverage'], source('SHAP explanation framework', 'https://shap.readthedocs.io/en/latest/')),
};

/** Subject-specific explanation for each Evidence workspace. */
/** Evidence tab id → its research guide, read from the tab registry. */
export const EVIDENCE_GUIDES: Record<string, string> = Object.fromEntries(EVIDENCE_TABS.map(t => [t.id, t.guide]));
export const GUIDE_ALIASES: Record<string, string> = { esm: 'esm1b', esmc_llr: 'esmc', gerp_rs: 'gerp', phyloP: 'phylop', alphaMissense: 'am' };
export function resolveResearchGuide(key: string): ResearchGuide | undefined {
  return RESEARCH_GUIDES[GUIDE_ALIASES[key] ?? key];
}

